  insert into public.sada_spec_versao (nome, arquivo_nome, vigente)
  insert into public.sada_spec_campo
    (versao_id, aba, campo, ordem, criticidade, formato, descricao, regras)
  values
  (v, 'METADADOS', 'Ente_Federativo', 0, 'Essencial', 'Texto', 'Nome oficial do município (ou ente) a que se referem todos os dados enviados neste arquivo.', 'Preencher uma única linha de resposta nesta aba. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'METADADOS', 'CNPJ_Ente', 1, 'Essencial', 'Texto — somente dígitos: 11 (CPF) ou 14 (CNPJ)', 'CNPJ do ente que está enviando os dados. Identifica oficialmente o ente na base recebida.', 'Somente números, sem pontos, barra ou traço. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'METADADOS', 'UF', 2, 'Importante', 'Texto — 2 letras', 'Sigla da unidade federativa do ente.', 'Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'METADADOS', 'Data_Base', 3, 'Essencial', 'Data — DD/MM/AAAA', 'Data a que se referem todos os saldos e todas as situações informados nas demais abas. É a fotografia da base.', 'Os saldos das abas ESTOQUE DA e PARCELAMENTO devem estar posicionados exatamente nesta data.'),
  (v, 'METADADOS', 'Data_Extracao', 4, 'Importante', 'Data — DD/MM/AAAA', 'Data em que a extração dos dados foi efetivamente executada no sistema.', 'Pode ser posterior à Data_Base. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'METADADOS', 'Periodo_Inicial', 5, 'Essencial', 'Data — DD/MM/AAAA', 'Primeiro dia do período coberto pela extração.', 'O período deve cobrir, no mínimo, os últimos 10 anos. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'METADADOS', 'Periodo_Final', 6, 'Essencial', 'Data — DD/MM/AAAA', 'Último dia do período coberto pela extração.', 'Normalmente igual à Data_Base. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'METADADOS', 'Sistema_Origem', 7, 'Importante', 'Texto', 'Nome do sistema de tributação/arrecadação de onde os dados foram extraídos.', 'Se houver mais de um sistema no período, informar todos separados por ponto-e-vírgula e indicar na aba DE-PARA o período de cada um.'),
  (v, 'METADADOS', 'Versao_Sistema', 8, 'Importante', 'Texto', 'Versão ou release do sistema utilizado na extração.', null),
  (v, 'METADADOS', 'Fornecedor_Sistema', 9, 'Complementar', 'Texto', 'Empresa fornecedora/responsável pelo sistema.', 'Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'METADADOS', 'Tabela_Dominio_Situacao', 10, 'Essencial', 'Texto', 'Confirmação de que a relação completa dos códigos de Situação usados pelo sistema, com a respectiva descrição, foi informada na aba DE-PARA.', 'Sem essa relação não é possível interpretar os campos Situacao das demais abas.'),
  (v, 'METADADOS', 'Responsavel_Tecnico', 11, 'Essencial', 'Texto', 'Nome do servidor ou técnico que gerou a extração e pode esclarecer dúvidas sobre os dados.', 'Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'METADADOS', 'Email_Responsavel', 12, 'Essencial', 'Texto', 'E-mail de contato do responsável técnico.', 'Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'METADADOS', 'Telefone_Responsavel', 13, 'Importante', 'Texto', 'Telefone de contato do responsável técnico.', 'Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'METADADOS', 'Observacoes', 14, 'Complementar', 'Texto', 'Espaço livre para registrar limitações da extração, campos indisponíveis, trocas de sistema ou qualquer ressalva sobre os dados enviados.', 'Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'LANÇAMENTO', 'ID_Lancamento', 0, 'Essencial', 'Texto — até 40 caracteres', 'Código que identifica de forma única cada lançamento (cada parcela lançada) na base do ente. É a chave que permite reencontrar o mesmo crédito nas abas RECEBIMENTO, ESTOQUE DA e RECEBIMENTO DA.', 'Não pode se repetir dentro desta aba. Pode ser o identificador interno do sistema. Se o sistema não possuir um código único, informar na aba DE-PARA qual combinação de campos identifica o lançamento. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'LANÇAMENTO', 'Cod_Evento', 1, 'Essencial', 'Texto', 'Código da rubrica de receita que o sistema atribui ao lançamento. Identifica qual é o tributo ou a receita lançada.', 'Todo código utilizado no período deve constar da aba DE-PARA, com a sua descrição e a receita padrão correspondente — inclusive códigos desativados.'),
  (v, 'LANÇAMENTO', 'Descri_Evento', 2, 'Essencial', 'Texto', 'Descrição da rubrica correspondente ao Cod_Evento, exatamente como está cadastrada no sistema.', 'Não abreviar, corrigir nem padronizar: enviar o texto original do sistema. TODAS as descrições utilizadas — inclusive variações da mesma receita ao longo do período (ex.: IPTU, I.P.T.U., IMPOSTO PREDIAL E TERRITORIAL URBANO) — devem ser relacionadas e mapeadas na aba DE-PARA.'),
  (v, 'LANÇAMENTO', 'CPF_CNPJ', 3, 'Essencial', 'Texto — somente dígitos: 11 (CPF) ou 14 (CNPJ)', 'Documento do contribuinte responsável pelo lançamento. É o identificador que permite reunir todos os créditos de um mesmo contribuinte.', 'Somente números, preservando zeros à esquerda. Não mascarar nem anonimizar.'),
  (v, 'LANÇAMENTO', 'Situacao', 4, 'Essencial', 'Texto — usar um dos valores da aba DOMÍNIOS', 'Situação em que o lançamento se encontra na Data_Base: pago, em aberto, parcelado, inscrito em dívida ativa, cancelado, suspenso, entre outras.', 'Se o sistema usar códigos próprios, enviá-los como estão e mapeá-los na aba DE-PARA.'),
  (v, 'LANÇAMENTO', 'Ano_Competencia', 5, 'Importante', 'Número inteiro — ano com 4 dígitos (AAAA)', 'Exercício a que o crédito se refere, que pode ser diferente do ano em que o lançamento foi gerado.', 'Ex.: ISS apurado em 2018 e lançado de ofício em 2020 tem competência 2018. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'LANÇAMENTO', 'Data_Geracao', 6, 'Essencial', 'Data — DD/MM/AAAA', 'Data em que o lançamento foi constituído/gerado no sistema.', 'Define a safra do lançamento.'),
  (v, 'LANÇAMENTO', 'Data_Vencimento', 7, 'Essencial', 'Data — DD/MM/AAAA', 'Data de vencimento da parcela lançada.', 'Enviar a data completa. Não substituir por mês/ano.'),
  (v, 'LANÇAMENTO', 'Num_Parcela', 8, 'Importante', 'Número inteiro', 'Número da parcela (cota) do tributo dentro do próprio lançamento.', 'Para cota única informar 1. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'LANÇAMENTO', 'Qtd_Parcelas', 9, 'Importante', 'Número inteiro', 'Quantidade total de parcelas (cotas) em que o tributo foi dividido no lançamento.', 'Para cota única informar 1. Cada parcela deve vir como uma linha própria. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'LANÇAMENTO', 'Valor_Original', 10, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Valor da parcela lançada, sem correção monetária, juros, multa ou desconto.', 'Sempre positivo.'),
  (v, 'LANÇAMENTO', 'Inscricao_Imobiliaria', 11, 'Importante', 'Texto', 'Código do cadastro do imóvel ao qual o lançamento se vincula. Identifica o imóvel na base do ente.', 'Preencher apenas para tributos imobiliários; deixar em branco nos demais.'),
  (v, 'LANÇAMENTO', 'Inscricao_Mobiliaria', 12, 'Importante', 'Texto', 'Código do cadastro econômico (empresa ou profissional autônomo) ao qual o lançamento se vincula. Identifica o contribuinte econômico na base do ente.', 'Preencher apenas para tributos e taxas de atividade econômica; deixar em branco nos demais.'),
  (v, 'RECEBIMENTO', 'ID_Lancamento', 0, 'Essencial', 'Texto — até 40 caracteres', 'Mesmo código informado na aba LANÇAMENTO, indicando a qual lançamento o pagamento se refere. É a chave que liga o que foi lançado ao que foi pago.', 'Todo ID_Lancamento desta aba deve existir na aba LANÇAMENTO. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'RECEBIMENTO', 'ID_Parcelamento', 1, 'Importante', 'Texto — até 40 caracteres', 'Código do acordo/parcelamento a que o pagamento pertence. É a chave que liga o pagamento à aba PARCELAMENTO.', 'Deixar em branco quando o pagamento não decorrer de acordo. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'RECEBIMENTO', 'Cod_Evento', 2, 'Essencial', 'Texto', 'Código da rubrica de receita a que o pagamento se refere.', 'Mesmo código informado na aba LANÇAMENTO.'),
  (v, 'RECEBIMENTO', 'Descri_Evento', 3, 'Essencial', 'Texto', 'Descrição da rubrica correspondente ao Cod_Evento, exatamente como cadastrada no sistema.', 'Enviar o texto original do sistema, sem padronizar. Toda descrição utilizada deve estar relacionada na aba DE-PARA.'),
  (v, 'RECEBIMENTO', 'CPF_CNPJ', 4, 'Essencial', 'Texto — somente dígitos: 11 (CPF) ou 14 (CNPJ)', 'Documento do contribuinte que efetuou o pagamento. É o identificador que liga o pagamento ao devedor.', 'Somente números, preservando zeros à esquerda.'),
  (v, 'RECEBIMENTO', 'Situacao', 5, 'Essencial', 'Texto — usar um dos valores da aba DOMÍNIOS', 'Situação do pagamento registrada no sistema: pago integral, pago parcial, pago em atraso, pago via parcelamento ou estornado.', 'Estornos e cancelamentos de pagamento também devem ser enviados.'),
  (v, 'RECEBIMENTO', 'Data_Acordo', 6, 'Essencial', 'Data — DD/MM/AAAA', 'Data de adesão ao acordo/parcelamento que originou o pagamento.', 'Deixar em branco quando o pagamento não decorrer de acordo.'),
  (v, 'RECEBIMENTO', 'Data_Vencimento', 7, 'Essencial', 'Data — DD/MM/AAAA', 'Data de vencimento da parcela paga.', 'Quando o pagamento decorrer de acordo, é o vencimento da parcela do acordo.'),
  (v, 'RECEBIMENTO', 'Valor_Original_Parcela', 8, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parte do valor pago correspondente ao principal, sem acréscimos.', 'Sempre positivo.'),
  (v, 'RECEBIMENTO', 'Valor_Correcao', 9, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parte do valor pago correspondente à correção monetária/atualização.', 'Informar 0,00 quando não houver.'),
  (v, 'RECEBIMENTO', 'Valor_Juros', 10, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parte do valor pago correspondente aos juros de mora.', 'Informar 0,00 quando não houver.'),
  (v, 'RECEBIMENTO', 'Valor_Multa', 11, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parte do valor pago correspondente à multa.', 'Informar 0,00 quando não houver.'),
  (v, 'RECEBIMENTO', 'Valor_Desconto', 12, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Valor do desconto, remissão ou anistia concedido no pagamento.', 'Informar como número positivo; ele é subtraído no Valor_Arrecadado.'),
  (v, 'RECEBIMENTO', 'Honorarios_Adv', 13, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parte do valor pago correspondente a honorários advocatícios e encargos de cobrança.', 'Informar 0,00 quando não houver.'),
  (v, 'RECEBIMENTO', 'Valor_Arrecadado', 14, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Valor efetivamente ingressado no caixa do ente nesse pagamento.', 'Deve corresponder a: Original + Correção + Juros + Multa + Honorários − Desconto.'),
  (v, 'RECEBIMENTO', 'Data_Arrecadacao', 15, 'Essencial', 'Data — DD/MM/AAAA', 'Data em que o pagamento foi efetivamente arrecadado (data do crédito/baixa no sistema).', 'Enviar a data completa. Não substituir por mês/ano.'),
  (v, 'ESTOQUE DA', 'ID_Lancamento', 0, 'Essencial', 'Texto — até 40 caracteres', 'Mesmo código informado na aba LANÇAMENTO, indicando qual lançamento deu origem à inscrição. É a chave que liga o crédito inscrito ao seu lançamento de origem.', 'Se uma mesma CDA reunir vários lançamentos, repetir a linha para cada lançamento ou explicar na aba DE-PARA como a amarração é feita. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'ESTOQUE DA', 'Num_CDA', 1, 'Essencial', 'Texto', 'Número da Certidão de Dívida Ativa. Identifica o crédito já inscrito em dívida ativa.', 'Enviar como texto, preservando zeros à esquerda. Junto com o Ano_Inscricao forma a identificação única da CDA.'),
  (v, 'ESTOQUE DA', 'Ano_Inscricao', 2, 'Essencial', 'Número inteiro — ano com 4 dígitos (AAAA)', 'Ano em que a CDA foi inscrita. Compõe a identificação da CDA e define a safra de inscrição.', null),
  (v, 'ESTOQUE DA', 'Cod_Evento', 3, 'Essencial', 'Texto', 'Código da rubrica de receita que originou o crédito inscrito.', null),
  (v, 'ESTOQUE DA', 'Descri_Evento', 4, 'Essencial', 'Texto', 'Descrição da rubrica correspondente ao Cod_Evento, exatamente como cadastrada no sistema.', 'Enviar o texto original do sistema, sem padronizar. Toda descrição utilizada deve estar relacionada na aba DE-PARA.'),
  (v, 'ESTOQUE DA', 'CPF_CNPJ', 5, 'Essencial', 'Texto — somente dígitos: 11 (CPF) ou 14 (CNPJ)', 'Documento do devedor do crédito inscrito. É o identificador que reúne todas as CDAs de um mesmo devedor.', 'Somente números, preservando zeros à esquerda.'),
  (v, 'ESTOQUE DA', 'Situacao', 6, 'Essencial', 'Texto — usar um dos valores da aba DOMÍNIOS', 'Situação do crédito inscrito na Data_Base: em aberto, em cobrança administrativa, protestado, ajuizado, parcelado, quitado, cancelado, prescrito ou cedido.', 'Informar a situação vigente na Data_Base; o histórico é reconstituído pelas datas de movimentação.'),
  (v, 'ESTOQUE DA', 'Data_Vencimento', 7, 'Essencial', 'Data — DD/MM/AAAA', 'Data de vencimento original do crédito que deu origem à inscrição.', 'Enviar a data completa.'),
  (v, 'ESTOQUE DA', 'Valor_Original_Parcela', 8, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parcela do saldo devedor na Data_Base correspondente ao principal.', 'Composição do estoque.'),
  (v, 'ESTOQUE DA', 'Valor_Correcao', 9, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parcela do saldo devedor na Data_Base correspondente à correção monetária/atualização.', 'Composição do estoque.'),
  (v, 'ESTOQUE DA', 'Valor_Juros', 10, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parcela do saldo devedor na Data_Base correspondente aos juros de mora.', 'Composição do estoque.'),
  (v, 'ESTOQUE DA', 'Valor_Multa', 11, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parcela do saldo devedor na Data_Base correspondente à multa.', 'Composição do estoque.'),
  (v, 'ESTOQUE DA', 'Valor_Estoque', 12, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Saldo devedor total do crédito na Data_Base, já deduzidos os pagamentos e abatimentos ocorridos.', 'Créditos quitados, cancelados, prescritos ou já cedidos devem vir com 0,00.'),
  (v, 'ESTOQUE DA', 'Data_Inscricao_DA', 13, 'Essencial', 'Data — DD/MM/AAAA', 'Data em que o crédito foi inscrito em dívida ativa.', 'Enviar a data completa.'),
  (v, 'ESTOQUE DA', 'Data_Ult_Movimentacao_Adm', 14, 'Essencial', 'Data — DD/MM/AAAA', 'Data do último ato de cobrança administrativa praticado sobre o crédito.', 'Deixar em branco se nenhum ato administrativo foi praticado.'),
  (v, 'ESTOQUE DA', 'Tipo_Ult_Movimentacao_Adm', 15, 'Essencial', 'Texto — usar um dos valores da aba DOMÍNIOS', 'Descrição do último ato de cobrança administrativa praticado: notificação, protesto, inscrição, adesão a parcelamento, rompimento, cancelamento, entre outros.', 'Identifica atos com efeito interruptivo ou suspensivo.'),
  (v, 'ESTOQUE DA', 'Ind_Ajuizado', 16, 'Essencial', 'Texto — "S" ou "N"', 'Indica se o crédito foi ajuizado por meio de execução fiscal.', null),
  (v, 'ESTOQUE DA', 'Data_Ajuizamento', 17, 'Importante', 'Data — DD/MM/AAAA', 'Data de distribuição da execução fiscal.', 'Preencher somente quando Ind_Ajuizado = S.'),
  (v, 'ESTOQUE DA', 'Num_Processo', 18, 'Importante', 'Texto', 'Número do processo judicial de execução fiscal. Identifica o crédito no Judiciário e permite rastrear seu andamento.', 'Enviar no padrão CNJ quando disponível.'),
  (v, 'ESTOQUE DA', 'Data_Ult_Movimentacao_Jud', 19, 'Essencial', 'Data — DD/MM/AAAA', 'Data da última movimentação registrada no processo judicial.', 'Preencher somente quando houver processo.'),
  (v, 'ESTOQUE DA', 'Tipo_Ult_Movimentacao_Jud', 20, 'Importante', 'Texto — usar um dos valores da aba DOMÍNIOS', 'Descrição da última movimentação registrada no processo judicial: distribuição, citação, penhora, suspensão pelo art. 40, arquivamento, extinção, entre outras.', null),
  (v, 'ESTOQUE DA', 'Data_Citacao', 21, 'Importante', 'Data — DD/MM/AAAA', 'Data em que o devedor foi citado na execução fiscal.', 'Deixar em branco quando não houve citação.'),
  (v, 'ESTOQUE DA', 'Ind_Suspenso_Art40', 22, 'Importante', 'Texto — "S" ou "N"', 'Indica se o processo está suspenso ou arquivado nos termos do art. 40 da Lei 6.830/80.', 'Coluna desmembrada para permitir filtro e contagem. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'ESTOQUE DA', 'Data_Suspensao_Art40', 23, 'Importante', 'Data — DD/MM/AAAA', 'Data da decisão que determinou a suspensão do art. 40.', 'Preencher somente quando Ind_Suspenso_Art40 = S.'),
  (v, 'ESTOQUE DA', 'Ind_Protestado', 24, 'Essencial', 'Texto — "S" ou "N"', 'Indica se a CDA foi levada a protesto em cartório.', 'Se o controle do protesto for feito fora do sistema, enviar também a planilha de controle da PGM.'),
  (v, 'ESTOQUE DA', 'Data_Protesto', 25, 'Essencial', 'Data — DD/MM/AAAA', 'Data em que a CDA foi protestada.', 'Preencher somente quando Ind_Protestado = S.'),
  (v, 'ESTOQUE DA', 'Ind_Exigibilidade_Suspensa', 26, 'Essencial', 'Texto — "S" ou "N"', 'Indica se a exigibilidade do crédito está suspensa na Data_Base.', null),
  (v, 'ESTOQUE DA', 'Motivo_Suspensao', 27, 'Importante', 'Texto — usar um dos valores da aba DOMÍNIOS', 'Motivo da suspensão da exigibilidade: parcelamento, liminar, depósito judicial, recurso administrativo, entre outros.', 'Preencher somente quando Ind_Exigibilidade_Suspensa = S.'),
  (v, 'ESTOQUE DA', 'Inscricao_Imobiliaria', 28, 'Importante', 'Texto', 'Código do cadastro do imóvel vinculado ao crédito inscrito. Identifica o imóvel na base do ente.', 'Preencher apenas para créditos imobiliários.'),
  (v, 'ESTOQUE DA', 'Inscricao_Mobiliaria', 29, 'Importante', 'Texto', 'Código do cadastro econômico vinculado ao crédito inscrito. Identifica o contribuinte econômico na base do ente.', 'Preencher apenas para créditos de atividade econômica.'),
  (v, 'ESTOQUE DA', 'Ind_Ja_Cedido', 30, 'Importante', 'Texto — "S" ou "N"', 'Indica se o crédito já foi objeto de cessão em operação anterior.', null),
  (v, 'ESTOQUE DA', 'ID_Parcelamento', 31, 'Importante', 'Texto — até 40 caracteres', 'Código do acordo/parcelamento em que o crédito inscrito está incluído. É a chave que liga a CDA à aba PARCELAMENTO.', 'Deixar em branco quando o crédito não estiver parcelado. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'RECEBIMENTO DA', 'ID_Lancamento', 0, 'Essencial', 'Texto — até 40 caracteres', 'Mesmo código informado na aba LANÇAMENTO, indicando a qual lançamento o pagamento se refere. É a chave que liga o recebimento de dívida ativa ao crédito de origem.', 'Todo ID_Lancamento desta aba deve existir nas abas LANÇAMENTO e ESTOQUE DA. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'RECEBIMENTO DA', 'Num_CDA', 1, 'Essencial', 'Texto', 'Número da Certidão de Dívida Ativa que está sendo paga. Identifica o crédito inscrito objeto do pagamento.', 'Deve existir na aba ESTOQUE DA. Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'RECEBIMENTO DA', 'Ano_Inscricao', 2, 'Essencial', 'Número inteiro — ano com 4 dígitos (AAAA)', 'Ano de inscrição da CDA que está sendo paga. Compõe a identificação da CDA.', 'Campo sugerido pela FIA (não constava da versão anterior).'),
  (v, 'RECEBIMENTO DA', 'ID_Parcelamento', 3, 'Importante', 'Texto — até 40 caracteres', 'Código do acordo/parcelamento a que o pagamento pertence. É a chave que liga o pagamento à aba PARCELAMENTO.', 'Deixar em branco quando o pagamento não decorrer de acordo.'),
  (v, 'RECEBIMENTO DA', 'Cod_Evento', 4, 'Essencial', 'Texto', 'Código da rubrica de receita a que o pagamento se refere.', 'Mesmo código informado na aba LANÇAMENTO.'),
  (v, 'RECEBIMENTO DA', 'Descri_Evento', 5, 'Essencial', 'Texto', 'Descrição da rubrica correspondente ao Cod_Evento, exatamente como cadastrada no sistema.', 'Enviar o texto original do sistema, sem padronizar. Toda descrição utilizada deve estar relacionada na aba DE-PARA.'),
  (v, 'RECEBIMENTO DA', 'CPF_CNPJ', 6, 'Essencial', 'Texto — somente dígitos: 11 (CPF) ou 14 (CNPJ)', 'Documento do contribuinte que efetuou o pagamento. É o identificador que liga o pagamento ao devedor.', 'Somente números, preservando zeros à esquerda.'),
  (v, 'RECEBIMENTO DA', 'Situacao', 7, 'Essencial', 'Texto — usar um dos valores da aba DOMÍNIOS', 'Situação do pagamento registrada no sistema: pago integral, pago parcial, pago em atraso, pago via parcelamento ou estornado.', 'Estornos e cancelamentos de pagamento também devem ser enviados.'),
  (v, 'RECEBIMENTO DA', 'Data_Acordo', 8, 'Essencial', 'Data — DD/MM/AAAA', 'Data de adesão ao acordo/parcelamento que originou o pagamento.', 'Deixar em branco quando o pagamento não decorrer de acordo.'),
  (v, 'RECEBIMENTO DA', 'Data_Vencimento', 9, 'Essencial', 'Data — DD/MM/AAAA', 'Data de vencimento da parcela paga.', 'Quando o pagamento decorrer de acordo, é o vencimento da parcela do acordo.'),
  (v, 'RECEBIMENTO DA', 'Valor_Original_Parcela', 10, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parte do valor pago correspondente ao principal, sem acréscimos.', 'Sempre positivo.'),
  (v, 'RECEBIMENTO DA', 'Valor_Correcao', 11, 'Essencial', 'Número decimal com 2 casas (ex.: 1.234,56)', 'Parte do valor pago correspondente à correção monetária/atualização.', 'Informar 0,00 quando não houver.'),
